<?php
session(); include('../include/config.php'); require_once __DIR__.'/module_bootstrap.php'; hms_module_require_roles(array('admin','doctor','perawat'));
if($_SERVER['REQUEST_METHOD']==='POST'){ hms_module_csrf(); $pid=(int)($_POST['patient_id']??0); $name=trim($_POST['patient_name']??''); $level=$_POST['triage_level']??'HIJAU'; $complaint=trim($_POST['chief_complaint']??''); $vitals=trim($_POST['vital_signs']??''); $action=trim($_POST['emergency_action']??''); $disp=$_POST['disposition']??'OBSERVASI'; $serviceId=(int)($_POST['service_id']??0);
 if(!in_array($level,array('MERAH','KUNING','HIJAU','HITAM'),true))$level='HIJAU'; if(!in_array($disp,array('RAWAT_INAP','PULANG','RUJUK','OBSERVASI'),true))$disp='OBSERVASI';
 if($pid<=0 && $name!==''){ $st=mysqli_prepare($con,'SELECT ID FROM tblpatient WHERE PatientName=? ORDER BY ID DESC LIMIT 1'); if($st){mysqli_stmt_bind_param($st,'s',$name);mysqli_stmt_execute($st);$x=mysqli_fetch_assoc(mysqli_stmt_get_result($st));$pid=(int)($x['ID']??0);mysqli_stmt_close($st);} }
 if($pid<=0){hms_set_flash('danger','Pasien tidak ditemukan. Pilih pasien yang sudah terdaftar.');}
 else { mysqli_begin_transaction($con); try {
   $visitCode=hms_module_next_code($con,'hms_patient_visits','REG','id'); $queue=hms_module_next_queue($con,'IGD');
   $st=mysqli_prepare($con,"INSERT INTO hms_patient_visits(patient_id,registration_no,visit_date,visit_type,poli,queue_no,source,status) VALUES(?,?,CURDATE(),'IGD','IGD',?,'OFFLINE','DILAYANI')"); mysqli_stmt_bind_param($st,'iss',$pid,$visitCode,$queue); if(!mysqli_stmt_execute($st))throw new RuntimeException('Kunjungan IGD gagal dibuat.'); $visitId=mysqli_stmt_insert_id($st); mysqli_stmt_close($st);
   $code=hms_module_next_code($con,'hms_igd_visits','IGD','id'); $doctorId=hms_module_current_role()==='doctor'?(int)($_SESSION['id']??0):0;
   $st=mysqli_prepare($con,"INSERT INTO hms_igd_visits(visit_id,patient_id,registration_no,triage_level,chief_complaint,vital_signs,emergency_action,doctor_id,disposition) VALUES(?,?,?,?,?,?,?,?,?)"); mysqli_stmt_bind_param($st,'iisssssis',$visitId,$pid,$code,$level,$complaint,$vitals,$action,$doctorId,$disp); if(!mysqli_stmt_execute($st))throw new RuntimeException('Registrasi IGD gagal.'); $id=mysqli_stmt_insert_id($st); mysqli_stmt_close($st);
   if($disp==='PULANG' || $disp==='RUJUK') hms_execute($con,"UPDATE hms_igd_visits SET status='SELESAI' WHERE id=?",'i',array($id));
   mysqli_commit($con);
   hms_module_workflow_event($con,$pid,$visitId,null,$id,'IGD_TRIAGE','SELESAI','Registrasi dan triase IGD dibuat.');
   if($disp==='RAWAT_INAP') hms_module_workflow_event($con,$pid,$visitId,null,$id,'IGD_DISPOSITION','MENUNGGU_ADMISSION','Pasien IGD ditetapkan untuk rawat inap.');
   elseif($disp==='PULANG') hms_module_workflow_event($con,$pid,$visitId,null,$id,'IGD_DISPOSITION','PULANG','Pasien IGD dipulangkan.');
   elseif($disp==='RUJUK') hms_module_workflow_event($con,$pid,$visitId,null,$id,'IGD_DISPOSITION','RUJUK','Pasien IGD ditetapkan untuk rujukan.');
   if($serviceId>0){ $svc=hms_fetch_one($con,'SELECT * FROM hms_service_catalog WHERE id=? AND is_active=1','i',array($serviceId)); if($svc){ try { hms_module_post_charge($con,$pid,$visitId,null,null,$id,$serviceId,'IGD',$svc['service_name'],1,(float)$svc['price']); } catch(Throwable $ce){ hms_set_flash('warning','IGD tersimpan, tetapi charge billing gagal: '.$ce->getMessage()); } } }
   hms_module_audit($con,'CREATE','IGD','hms_igd_visits',$id,'Registrasi IGD dan kunjungan dibuat',null,array('patient_id'=>$pid,'visit_id'=>$visitId,'triage_level'=>$level,'disposition'=>$disp)); hms_set_flash('success','Registrasi IGD tersimpan: '.$code.' / '.$visitCode);
 } catch(Throwable $e){mysqli_rollback($con);hms_set_flash('danger',$e->getMessage());} } }
$services=hms_fetch_all($con,"SELECT id,service_name,price FROM hms_service_catalog WHERE is_active=1 AND service_type IN ('IGD','TINDAKAN') ORDER BY service_name");
$rows=hms_fetch_all($con,"SELECT g.*, COALESCE(p.PatientName,'Pasien #') patient_name FROM hms_igd_visits g LEFT JOIN tblpatient p ON p.ID=g.patient_id ORDER BY g.id DESC LIMIT 100"); $role=hms_module_current_role(); hms_layout_header('Instalasi Gawat Darurat',$role,'operations');
?>
<div class="hms-page-title"><div><h1>Instalasi Gawat Darurat (IGD)</h1><div class="text-muted">Registrasi cepat, triase, tindakan darurat dan disposisi pasien.</div></div></div>
<div class="hms-card p-3 mb-4"><form method="post" class="row g-3"><?php echo hms_csrf_field(); ?><div class="col-md-3"><label class="form-label">Nama pasien</label><input name="patient_name" class="form-control" required></div><div class="col-md-2"><label class="form-label">Triase</label><select name="triage_level" class="form-select"><option>MERAH</option><option>KUNING</option><option>HIJAU</option><option>HITAM</option></select></div><div class="col-md-3"><label class="form-label">Keluhan utama</label><textarea name="chief_complaint" class="form-control" rows="2"></textarea></div><div class="col-md-2"><label class="form-label">Tanda vital</label><input name="vital_signs" class="form-control" placeholder="TD/Nadi/Suhu/SpO2"></div><div class="col-md-2"><label class="form-label">Disposisi</label><select name="disposition" class="form-select"><option>OBSERVASI</option><option>RAWAT_INAP</option><option>PULANG</option><option>RUJUK</option></select></div><div class="col-md-3"><label class="form-label">Layanan otomatis ke billing</label><select name="service_id" class="form-select"><option value="0">Tidak ada</option><?php foreach($services as $sv){ ?><option value="<?php echo (int)$sv['id']; ?>"><?php echo hms_e($sv['service_name'].' - Rp '.number_format($sv['price'],0,',','.')); ?></option><?php } ?></select></div><div class="col-12"><label class="form-label">Tindakan darurat</label><textarea name="emergency_action" class="form-control" rows="2"></textarea></div><div class="col-12"><button class="btn btn-danger">Simpan Registrasi IGD</button></div></form></div>
<div class="hms-card p-3"><div class="table-responsive"><table class="table table-hover"><thead><tr><th>No IGD</th><th>Pasien</th><th>Triase</th><th>Keluhan</th><th>Disposisi</th><th>Datang</th></tr></thead><tbody><?php foreach($rows as $r){ ?><tr><td><?php echo hms_e($r['registration_no']); ?></td><td><?php echo hms_e($r['patient_name']); ?></td><td><?php echo hms_e($r['triage_level']); ?></td><td><?php echo hms_e($r['chief_complaint']); ?></td><td><?php echo hms_e($r['disposition']); ?></td><td><?php echo hms_e($r['arrival_time']); ?></td></tr><?php } ?></tbody></table></div></div>
<?php hms_layout_footer(); ?>
